fn main() {
    // App icon (assets/raisin.ico, generated by tools/make-icons.ps1).
    println!("cargo:rerun-if-changed=assets/raisin.rc");
    println!("cargo:rerun-if-changed=assets/raisin.ico");
    embed_resource::compile("assets/raisin.rc", embed_resource::NONE)
        .manifest_optional()
        .expect("failed to embed the app icon");

    // Embed a manifest so buttons/edits use modern (ComCtl v6) visuals.
    if std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        println!("cargo:rustc-link-arg-bins=/MANIFEST:EMBED");
        println!(
            "cargo:rustc-link-arg-bins=/MANIFESTDEPENDENCY:type='win32' \
             name='Microsoft.Windows.Common-Controls' version='6.0.0.0' \
             processorArchitecture='*' publicKeyToken='6595b64144ccf1df' language='*'"
        );
    }
}
